cd /workspace && tsc -p tsconfig.json && cat > /tmp/baseline.cjs <<'EOF'
const { renderInvoice } = require('/workspace/.build/invoice');
const { renderReport } = require('/workspace/.build/report');
const vals = [0, 1, 9, 10, 99, 100, 123, 1000, 12345, 999999, -1, -9, -10, -99, -100, -123, -12345, -999999];
const out = {
  inv: vals.map(v => renderInvoice('x', v)),
  rep: renderReport(vals.map((v, i) => ({ id: 'r' + i, cents: v }))),
};
console.log(JSON.stringify(out));
EOF
node /tmp/baseline.cjs > /tmp/baseline.json && cat /tmp/baseline.json && cp /tmp/baseline.json /tmp/baseline_saved.json

cd /workspace && cat > src/money.ts <<'EOF'
/**
 * Formats an integer amount of cents as a plain decimal string:
 * optional '-' sign, absolute whole units, and exactly two fraction digits.
 * No currency symbol is included.
 */
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
cat > src/invoice.ts <<'EOF'
import { formatAmount } from './money';
export function renderInvoice(id: string, cents: number): string { return id + ': $' + formatAmount(cents); }
EOF
cat > src/report.ts <<'EOF'
import { formatAmount } from './money';
export function renderReport(rows: { id: string; cents: number }[]): string {
  return rows.map(row => row.id + ',' + formatAmount(row.cents)).join('\n');
}
EOF
rm src/invoiceAmount.ts src/reportAmount.ts
cat >> checks/public.cjs <<'EOF'

const { formatAmount } = require('../.build/money');
assert.equal(formatAmount(0), '0.00');
assert.equal(formatAmount(1), '0.01');
assert.equal(formatAmount(123), '1.23');
assert.equal(formatAmount(12345), '123.45');
assert.equal(formatAmount(-1), '-0.01');
assert.equal(formatAmount(-123), '-1.23');
EOF
rm -rf .build && tsc -p tsconfig.json && node checks/public.cjs && echo PUBLIC_OK && node /tmp/baseline.cjs > /tmp/after.json && diff /tmp/baseline_saved.json /tmp/after.json && echo "BASELINE IDENTICAL"; echo "--- leftovers:"; grep -rn "invoiceAmount\|reportAmount" src checks || echo none; ls src
